import java.util.*;

class Solution {
    public String minWindow(String s, String need) {
        int[] cnt = new int[128];
        for (char c : need.toCharArray()) cnt[c]++;
        int missing = need.length(), left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            if (cnt[s.charAt(right)]-- > 0) missing--;      // this char was still needed
            while (missing == 0) {                          // window covers the wishlist
                if (right - left + 1 < bestLen) { bestLen = right - left + 1; bestStart = left; }
                if (++cnt[s.charAt(left++)] > 0) missing++;  // dropped a needed char
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }
}

