class Solution:
    def minWindow(self, s: str, need: str) -> str:
        req = Counter(need); missing = len(need); l = 0; bs, bl = 0, inf
        for r, c in enumerate(s):
            if req[c] > 0: missing -= 1
            req[c] -= 1
            while missing == 0:
                if r - l + 1 < bl: bs, bl = l, r - l + 1
                req[s[l]] += 1
                if req[s[l]] > 0: missing += 1
                l += 1
        return "" if bl == inf else s[bs:bs + bl]

