function minWindow(s, need) {
  const req = {}; for (const c of need) req[c] = (req[c] || 0) + 1;
  const keys = Object.keys(req);
  const n = s.length, pre = {}; for (const k of keys) { const a = [0]; for (const c of s) a.push(a[a.length - 1] + (c === k ? 1 : 0)); pre[k] = a; }
  const ok = (i, j) => keys.every(k => pre[k][j] - pre[k][i] >= req[k]);
  let best = "", bl = Infinity;
  for (let i = 0; i < n; i++) {
    if (!ok(i, n)) break;
    let lo = i + 1, hi = n; while (lo < hi) { const m = (lo + hi) >> 1; if (ok(i, m)) hi = m; else lo = m + 1; }
    if (lo - i < bl) { bl = lo - i; best = s.slice(i, lo); }
  }
  return best;
}
